<?php require_once __DIR__.'/../includes/functions.php';require_admin();$adminTitle='النسخ الاحتياطي';$file=null;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$tables=['admins','settings','hero','categories','products','customers','wilayas','communes','coupons','orders','order_items','reviews','faqs','homepage_sections','contact_messages','activity_logs','blacklists'];$dump="-- ALAN backup ".date('c')."\nSET NAMES utf8mb4;\nUSE alan_store;\n";foreach($tables as $table){$rows=db()->query("SELECT * FROM `$table`")->fetchAll();if($rows){$dump.="DELETE FROM `$table`;\n";foreach($rows as $row){$cols=array_map(fn($x)=>"`$x`",array_keys($row));$vals=array_map(fn($x)=>db()->quote((string)$x),array_values($row));$dump.='INSERT INTO `'.$table.'` ('.implode(',',$cols).') VALUES ('.implode(',',$vals).");\n";}}}$name='alan-backup-'.date('Ymd-His').'.sql';file_put_contents(__DIR__.'/../uploads/'.$name,$dump);$file=$name;log_activity('backup_created',$name);}include 'header.php';?><div class="panel"><h2>نسخة احتياطية يدوية</h2><p class="muted">ينشئ ملف SQL من بيانات المتجر الحالية في مجلد uploads.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><button class="button gold">إنشاء نسخة الآن</button></form><?php if($file):?><p>تم الإنشاء: <a href="<?=base('uploads/'.$file)?>"><?=e($file)?></a></p><?php endif;?></div><?php include 'footer.php';?>
